/* ---------------------------------------------------------- list skeleton
   The shape a table has before its rows arrive. `.skeleton` above supplies
   the shimmer; everything here is about **height**, which is the part that
   matters: a block that collapses to nothing lets the page settle at one
   height and then grow under the reader when the data lands. */

.table-skeleton {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-4);
}

.table-skeleton-row {
  display: grid;
  /* Set inline by the component, so a page's skeleton has the column
     count of the table it stands in rather than a guess. */
  grid-template-columns: repeat(var(--skeleton-columns, 4), minmax(0, 1fr));
  gap: var(--space-3);
  align-items: center;
  min-height: 20px;
}

/* A bar rather than a filled cell: a full-width block reads as content
   that failed to render, while a short bar reads as a placeholder. */
.table-skeleton-cell {
  display: block;
  height: 12px;
}

.skeleton-row td {
  /* Matches a real row's vertical padding, so the tbody does not change
     height when the rows are swapped in. */
  padding-block: var(--space-3);
}

@media (prefers-reduced-motion: reduce) {
  /* The shimmer is decoration; the height is the message. Motion goes,
     the placeholder stays. */
  .skeleton,
  .table-skeleton-cell {
    animation: none;
  }
}
